/* Python scripts could not enumerate a source's filters
 * (obsproject/obs-studio#12116, reported by Kevin-Kevin and confirmed by
 * Penwy): obspython exposed the C function obs_source_enum_filters(source,
 * callback, param) as generated by SWIG, which takes a C function pointer a
 * script cannot provide, so every call failed with a TypeError. Lua has
 * long wrapped it as obs_source_enum_filters(source) returning a table of
 * filter references, like obs_enum_sources() and obs_scene_enum_items(),
 * which Python already wraps the same way.
 *
 * The test loads a real Python script through obs-scripting. The script
 * enumerates the filters of a source that has two, logs their names, and
 * releases the list with source_list_release(). The test checks the names
 * and that no filter reference leaked: once the source is released, neither
 * filter can still be referenced.
 *
 * obs_startup() needs a display on Linux, so the cases skip without one
 * (run under xvfb-run). */

#include <stdarg.h>
#include <stddef.h>
#include <setjmp.h>
#include <cmocka.h>

#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <obs.h>
#include <obs-scripting.h>
#include <util/base.h>
#include <util/dstr.h>

#define SOURCE_ID "python_enum_filters_source"
#define FILTER_ID "python_enum_filters_filter"

static bool obs_up;
static bool scripting_up;
static struct dstr script_output;

static const char *source_name(void *type_data)
{
	(void)type_data;
	return "enum filters source";
}

static const char *filter_name(void *type_data)
{
	(void)type_data;
	return "enum filters filter";
}

static void *dummy_create(obs_data_t *settings, obs_source_t *source)
{
	(void)settings;
	return source;
}

static void source_destroy(void *data)
{
	(void)data;
}

static void quiet_log(int lvl, const char *msg, va_list args, void *p)
{
	(void)p;
	if (lvl <= LOG_WARNING) {
		vfprintf(stderr, msg, args);
		fputc('\n', stderr);
	}
}

static void script_log(void *param, obs_script_t *script, int lvl, const char *msg)
{
	(void)param;
	(void)script;
	(void)lvl;
	dstr_cat(&script_output, msg);
	dstr_cat(&script_output, "\n");
}

static const char *script_text = "import obspython as obs\n"
				 "\n"
				 "def script_load(settings):\n"
				 "    source = obs.obs_get_source_by_name('enum filters parent')\n"
				 "    try:\n"
				 "        filters = obs.obs_source_enum_filters(source)\n"
				 "        names = [obs.obs_source_get_name(f) for f in filters]\n"
				 "        obs.script_log(obs.LOG_INFO, 'filters=' + ','.join(names))\n"
				 "        obs.source_list_release(filters)\n"
				 "    except Exception as e:\n"
				 "        obs.script_log(obs.LOG_INFO, 'error=' + type(e).__name__ + ': ' + str(e))\n"
				 "    obs.obs_source_release(source)\n";

static void python_script_lists_filters(void **state)
{
	(void)state;
	if (!scripting_up)
		skip();

	obs_source_t *parent = obs_source_create(SOURCE_ID, "enum filters parent", NULL, NULL);
	obs_source_t *f1 = obs_source_create_private(FILTER_ID, "filter one", NULL);
	obs_source_t *f2 = obs_source_create_private(FILTER_ID, "filter two", NULL);
	assert_non_null(parent);
	assert_non_null(f1);
	assert_non_null(f2);
	obs_source_filter_add(parent, f1);
	obs_source_filter_add(parent, f2);
	obs_weak_source_t *weak1 = obs_source_get_weak_source(f1);
	obs_weak_source_t *weak2 = obs_source_get_weak_source(f2);
	obs_source_release(f1);
	obs_source_release(f2);

	struct dstr path = {0};
	const char *tmp = getenv("TMPDIR");
	dstr_printf(&path, "%s/test_python_enum_filters_%d.py", tmp && *tmp ? tmp : "/tmp", (int)getpid());
	FILE *f = fopen(path.array, "w");
	assert_non_null(f);
	fputs(script_text, f);
	fclose(f);

	dstr_free(&script_output);
	obs_script_t *script = obs_script_create(path.array, NULL);
	bool loaded = script && obs_script_loaded(script);
	obs_script_destroy(script);
	unlink(path.array);
	dstr_free(&path);

	if (!loaded) {
		fprintf(stderr, "the script did not load:\n%s\n", script_output.array ? script_output.array : "");
		fail();
	}

	const char *out = script_output.array ? script_output.array : "";
	if (!strstr(out, "filters=filter one,filter two")) {
		fprintf(stderr, "expected the script to list both filters, script log:\n%s\n", out);
		fail();
	}

	/* Every reference the script took must be gone: once the source drops
	 * its filters, no strong reference to them may remain. */
	obs_source_remove(parent);
	obs_source_release(parent);
	/* the source is destroyed, releasing its filters, on the destroy queue */
	obs_wait_for_destroy_queue();
	obs_source_t *left1 = obs_weak_source_get_source(weak1);
	obs_source_t *left2 = obs_weak_source_get_source(weak2);
	int leaked = (left1 != NULL) + (left2 != NULL);
	obs_source_release(left1);
	obs_source_release(left2);
	obs_weak_source_release(weak1);
	obs_weak_source_release(weak2);
	if (leaked) {
		fprintf(stderr, "%d of 2 filters are still referenced after their source was released\n", leaked);
		fail();
	}
}

static int setup(void **state)
{
	(void)state;
	base_set_log_handler(quiet_log, NULL);
	obs_up = obs_startup("en-US", NULL, NULL);
	if (!obs_up) {
		fprintf(stderr, "skipped: obs_startup failed (no display?)\n");
		return 0;
	}

	struct obs_source_info source_info = {
		.id = SOURCE_ID,
		.type = OBS_SOURCE_TYPE_INPUT,
		.output_flags = OBS_SOURCE_AUDIO,
		.get_name = source_name,
		.create = dummy_create,
		.destroy = source_destroy,
	};
	obs_register_source(&source_info);

	struct obs_source_info filter_info = {
		.id = FILTER_ID,
		.type = OBS_SOURCE_TYPE_FILTER,
		.output_flags = OBS_SOURCE_AUDIO,
		.get_name = filter_name,
		.create = dummy_create,
		.destroy = source_destroy,
	};
	obs_register_source(&filter_info);

	obs_scripting_set_log_callback(script_log, NULL);
	scripting_up = obs_scripting_load();
	if (!scripting_up)
		fprintf(stderr, "skipped: obs_scripting_load failed\n");
	return 0;
}

static int teardown(void **state)
{
	(void)state;
	if (scripting_up)
		obs_scripting_unload();
	if (obs_up)
		obs_shutdown();
	dstr_free(&script_output);
	return 0;
}

int main(void)
{
	const struct CMUnitTest tests[] = {
		cmocka_unit_test(python_script_lists_filters),
	};
	return cmocka_run_group_tests(tests, setup, teardown);
}
